const $=s=>document.querySelector(s),root=$('[data-stats-panel]'),note=$('[data-stats-status]');let report;
async function api(path,body){const r=await fetch('/api/analytics/'+path,{cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok){if(r.status===401){root.hidden=true;$('[data-stats-login]').hidden=false;}throw Error(data.error||'No se pudo obtener el informe.');}return data;}
const number=n=>new Intl.NumberFormat('es-ES',{maximumFractionDigits:1}).format(Number(n)||0);
function el(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;}
function table(name,rows,field='count'){const host=$('[data-stats-'+name+']');host.replaceChildren();if(!rows?.length){host.append(el('p','Aún no hay datos consentidos en este periodo.'));return;}const t=el('table');for(const row of rows){const tr=el('tr');tr.append(el('th',row.label),el('td',number(row[field])));if(row.active_ms)tr.append(el('td',number(row.active_ms/1000)+' s activos'));if(row.best_lap_ms)tr.append(el('td',(row.best_lap_ms/1000).toFixed(3)+' s · mejor vuelta'));t.append(tr);}host.append(t);}
function chart(){if(!report)return;const ga=report.source==='ga4',rows=report.current.daily||[],mode=$('[name=group]').value,groups=new Map();for(const r of rows){let key=r.label;if(ga)key=key.slice(0,4)+'-'+key.slice(4,6)+'-'+key.slice(6,8);if(mode==='week'){const d=new Date(key+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));key=d.toISOString().slice(0,10);}if(mode==='month')key=key.slice(0,7);groups.set(key,(groups.get(key)||0)+Number(ga?r.screenPageViews:r.views));}const max=Math.max(1,...groups.values()),host=$('[data-stats-chart]');host.replaceChildren();for(const [date,views]of groups){const item=el('div');item.className='stats-bar';item.style.setProperty('--bar-height',Math.max(1,views/max*140)+'px');item.title=date+': '+views+' páginas vistas';item.append(el('strong',number(views)),el('i'),el('small',date));host.append(item);}if(!groups.size)host.append(el('p','El gráfico aparecerá cuando haya visitas consentidas.'));}
function render(data){report=data;const ga=data.source==='ga4',s=ga?data.current.summary?.[0]||{}:data.current.summary||{},old=ga?data.previous.summary?.[0]||{}:data.previous.summary||{},fields=ga?[['Usuarios','totalUsers'],['Sesiones','sessions'],['Páginas vistas','screenPageViews'],['Interacción total (s)','userEngagementDuration']]:[['Visitantes únicos','users'],['Sesiones','sessions'],['Páginas vistas','views'],['Interacción total (s)','active_ms']],host=$('[data-stats-kpis]');host.replaceChildren();for(const [label,key]of fields){const v=Number(s[key])||0,p=Number(old[key])||0,unit=key==='active_ms'?1000:1,card=el('article');card.append(el('span',label),el('strong',number(v/unit)),el('small',p?(number((v-p)/p*100)+' % frente al periodo anterior'):'Periodo anterior sin datos'));host.append(card);}const engaged=Number(ga?s.engagedSessions:s.engaged)||0,sessions=Number(s.sessions)||0;for(const [label,value]of [['Sesiones con interacción',number(engaged)],['Participación',sessions?number(engaged/sessions*100)+' %':'0 %']]){const card=el('article');card.append(el('span',label),el('strong',value));host.append(card);}table('pages',data.current.pages,ga?'screenPageViews':'count');table('sections',data.current.sections||[]);table('events',data.current.events,ga?'eventCount':'count');table('sources',data.current.sources,ga?'sessions':'count');table('devices',data.current.devices,ga?'sessions':'count');chart();note.textContent=(ga?'Fuente: API de Google Analytics 4.':'Fuente: medición propia consentida.')+' Comparación con '+data.previousFrom+' — '+data.previousTo+'. '+(data.notice||'Las cifras de proveedores distintos nunca se suman.');}
async function load(){note.textContent='Cargando estadísticas…';try{const f=$('[data-stats-filters]');render(await api('report?'+new URLSearchParams({from:f.elements.from.value,to:f.elements.to.value,source:f.elements.source.value})));}catch(e){note.textContent=e.message;}}
$('[data-stats-filters]').onsubmit=e=>{e.preventDefault();void load();};$('[name=group]').onchange=chart;document.querySelectorAll('[data-stats-period]').forEach(b=>b.onclick=()=>{const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Madrid'}).format(new Date()),end=new Date(today+'T12:00:00Z'),start=new Date(end);start.setUTCDate(start.getUTCDate()-Number(b.dataset.statsPeriod)+1);$('[name=from]').value=start.toISOString().slice(0,10);$('[name=to]').value=end.toISOString().slice(0,10);void load();});
$('[data-stats-settings]').onsubmit=async e=>{e.preventDefault();const form=e.target,body=Object.fromEntries(new FormData(form));for(const key of ['GA4_PRIVACY_VERIFIED','CLARITY_MASKING_VERIFIED'])body[key]=form.elements[key].checked;try{await api('settings',body);$('[data-stats-config-status]').textContent='Identificadores guardados. La API de GA4 requiere además la credencial privada de servidor y permiso de lectura en la propiedad.';await status();}catch(e){$('[data-stats-config-status]').textContent=e.message;}};
async function status(){const s=await api('status'),host=$('[data-stats-providers]');host.replaceChildren();for(const [key,label]of [['ga4','GA4 · etiqueta'],['ga4Reports','GA4 · API privada'],['clarity','Clarity · grabaciones limitadas'],['cloudflare','Cloudflare Web Analytics']])host.append(el('li',label+': '+(s.providers[key]?'Configurado; pendiente de validar recepción externa':'Pendiente de configurar')));for(const [key,value]of Object.entries(s.settings||{})){const input=$('[data-stats-settings]').elements[key];if(input){if(input.type==='checkbox')input.checked=value==='1';else input.value=value;}}}
try{await api('status');root.hidden=false;$('[data-stats-login]').hidden=true;await status();$('[data-stats-period="7"]').click();}catch(e){note.textContent=e.message;}
